      's.pages.lead': 'Mỗi trang là một lưới widget 12 × 6. Chọn một trang ở bên trái, sắp xếp các widget của nó trên chiếc điện thoại bên dưới và đặt tùy chọn cho chúng. Kéo các trang để sắp xếp lại; trang đầu tiên là trang chủ mà bảng điều khiển quay về khi không hoạt động. Trên điện thoại, vuốt, dùng phím âm lượng, hoặc chạm vào các chấm (hoặc nhấn giữ một trang) để xem tổng quan tất cả các trang.',
