      'Target: hex MIDI bytes, e.g. B0 07 {value}. Device: numeric output port. Value: 0–127.': 'Đích: byte MIDI dạng hex, ví dụ B0 07 {value}. Thiết bị: cổng ra dạng số. Giá trị: 0–127.',
      'Target: OSC address, e.g. /volume. Device: host:port. Value: whole number (sent as an OSC float).': 'Đích: địa chỉ OSC, ví dụ /volume. Thiết bị: host:port. Giá trị: số nguyên (gửi dạng OSC float).',
