      'A live picture from an IP camera (RTSP), 5 frames a second by default (1 to 10). Add the camera in Settings › General › Cameras; the computer pulls it with ffmpeg, and its address stays there.': 'Hình ảnh trực tiếp từ camera IP (RTSP), mặc định 5 khung hình mỗi giây (1 đến 10). Thêm camera trong Cài đặt › Chung › Camera; máy tính sẽ kéo luồng bằng ffmpeg và địa chỉ camera chỉ lưu ở đó.',
